def _skip_ws(text: str, pos: int) -> int:
    # Process in fixed-size chunks to reduce loop overhead
    chunk_size = 64
    while True:
        try:
            # Process chunk by chunk
            end = min(pos + chunk_size, len(text))
            chunk = text[pos:end]
            ws_chars = {c for c in _WS_CHARS}
            ws_count = sum(1 for char in chunk if char in ws_chars)
